\mathsf{IndRule}_{coCIC}
=
\{(\langle\rangle,\operatorname{jdg}_{coCIC}
(\Gamma,\operatorname{ind}(I,\ell,\overline P),\operatorname{sort}(s_I))):
\begin{array}{l}
\Gamma\in\mathsf{Ctx}_{coCIC},\ I\in\operatorname{dom}(\mathcal I),\
\mathcal I(I)=(\ell_I,\bar p_I,\bar A_I,s_I,\bar c_I,\bar C_I),\\
\ell\in\mathbb N,\quad
\overline P\in(\mathsf{Exp}_{coCIC}^{\mathcal G})^{|\bar p_I|}
\end{array}\},

\mathsf{ConRule}_{coCIC}
=
\{(\langle\operatorname{jdg}_{coCIC}
(\Gamma,M_i,A_i[\bar z_{<i}:=\bar M_{<i}])\rangle_{i<r},
\operatorname{jdg}_{coCIC}
(\Gamma,\operatorname{con}(c,\bar M),
\operatorname{res}_{coCIC}(C)[\bar z:=\bar M])):
\begin{array}{l}
\Gamma\in\mathsf{Ctx}_{coCIC},\ I\in\operatorname{dom}(\mathcal I),\
c\in\operatorname{Ctor}_{coCIC}(I),\ C=\operatorname{CtorTy}_{coCIC}(I,c),\\
\operatorname{tel}_{coCIC}(C)=\langle(z_i,A_i)\rangle_{i<r},\
\bar M=\langle M_i\rangle_{i<r}\in(\mathsf{Exp}_{coCIC}^{\mathcal G})^r
\end{array}\},

\mathsf{FixRule}_{coCIC}
=
\{(\langle\operatorname{jdg}_{coCIC}
(\operatorname{ext}_{coCIC}(\operatorname{ext}_{coCIC}
(\Gamma,f,\operatorname{Pi}(x,A,B)),x,A),M,B)\rangle,
\operatorname{jdg}_{coCIC}(\Gamma,\operatorname{fix}(f,x,A,M),\operatorname{Pi}(x,A,B))):
\begin{array}{l}
\Gamma\in\mathsf{Ctx}_{coCIC},\ f,x\in\mathsf{Var}_{coCIC},\
A,B,M\in\mathsf{Exp}_{coCIC}^{\mathcal G},\
f,x\notin\operatorname{dom}(\Gamma),\ f\ne x,\\
\operatorname{ext}_{coCIC}(\operatorname{ext}_{coCIC}
(\Gamma,f,\operatorname{Pi}(x,A,B)),x,A)\in\mathsf{Ctx}_{coCIC},\
\mathsf{FixGuardCert}_{coCIC}(f,x,M)\ne\varnothing
\end{array}\}.

\mathsf{CoFixRule}_{coCIC}=
\{(\langle\operatorname{jdg}_{coCIC}
(\operatorname{ext}_{coCIC}(\operatorname{ext}_{coCIC}
(\Gamma,g,\operatorname{Pi}(x,A,B)),x,A),M,B)\rangle,
\operatorname{jdg}_{coCIC}(\Gamma,\operatorname{cofix}(g,x,A,M),\operatorname{Pi}(x,A,B))):
\begin{array}{l}
\Gamma\in\mathsf{Ctx}_{coCIC},\ g,x\in\mathsf{Var}_{coCIC},\
A,B,M\in\mathsf{Exp}_{coCIC}^{\mathcal G},\
g,x\notin\operatorname{dom}(\Gamma),\ g\ne x,\\
\operatorname{ext}_{coCIC}(\operatorname{ext}_{coCIC}
(\Gamma,g,\operatorname{Pi}(x,A,B)),x,A)\in\mathsf{Ctx}_{coCIC},\
\exists G\ (G\in\mathsf{ProdTree}_{coCIC}(g,M))
\end{array}\}.
